package com.bhagya.qa.performance;
import org.testng.Assert;import org.testng.annotations.*;import java.net.*;import java.net.http.*;import java.nio.file.*;
public class PerformancePlatformTest {private DemoService service;@BeforeClass public void start()throws Exception{service=new DemoService();service.start();}@Test public void healthEndpointReturnsUp()throws Exception{var r=HttpClient.newHttpClient().send(HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+service.getPort()+"/health")).GET().build(),HttpResponse.BodyHandlers.ofString());Assert.assertEquals(r.statusCode(),200);Assert.assertTrue(r.body().contains("UP"));}@Test(dependsOnMethods="healthEndpointReturnsUp")public void controlledLoadProducesMetrics()throws Exception{var r=new LoadTestEngine().execute("http://127.0.0.1:"+service.getPort(),10,5,"LOAD");Assert.assertEquals(r.totalRequests,50);Assert.assertEquals(r.failedRequests,0);Assert.assertTrue(r.throughputPerSecond>0);new ReportWriter().write(r);}@Test(dependsOnMethods="controlledLoadProducesMetrics")public void reportsAreGenerated(){Assert.assertTrue(Files.exists(Path.of("reports/summary.json")));Assert.assertTrue(Files.exists(Path.of("reports/performance-report.html")));Assert.assertTrue(Files.exists(Path.of("reports/requests.csv")));}@Test public void dashboardIncludesMetrics()throws Exception{String h=Files.readString(Path.of("dashboard/index.html"));Assert.assertTrue(h.contains("Response Time"));Assert.assertTrue(h.contains("Throughput"));Assert.assertTrue(h.contains("Error Rate"));}@AfterClass(alwaysRun=true)public void stop(){if(service!=null)service.stop();}}
